// Square viewport around the 512-high glyph, padded so it reads at Material's weight.
private const val BOX = 616f

private fun fa(name: String, width: Int, height: Int, d: String, inner: Triple<Int, Int, String>? = null): ImageVector =
    ImageVector.Builder(name = "osu.$name", defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = BOX, viewportHeight = BOX)
        .apply {
            group(translationX = (BOX - width) / 2f, translationY = (BOX - height) / 2f) {
                addPath(pathData = addPathNodes(d), fill = SolidColor(Color.Black))
            }
            if (inner != null) {
                val (w, h, innerD) = inner
                val scale = 0.42f
                group(
                    translationX = (BOX - w * scale) / 2f,
                    translationY = (BOX - h * scale) / 2f,
                    scaleX = scale,
                    scaleY = scale,
                ) {
                    addPath(pathData = addPathNodes(innerD), fill = SolidColor(Color.Black))
                }
            }
        }
        .build()
